import{i as e,r as t,s as n,t as r}from"./app-DuH0mZgh.js";var i=JSON.parse(`{"path":"/17-AOI_and_Scene_Design.html","title":"AOI 服务与场景调度设计","lang":"en-US","frontmatter":{},"filePathRelative":"17-AOI_and_Scene_Design.md","git":{"createdTime":1765122408000,"updatedTime":1765122408000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}]}}`),a={name:`17-AOI_and_Scene_Design.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="aoi-服务与场景调度设计" tabindex="-1"><a class="header-anchor" href="#aoi-服务与场景调度设计"><span>AOI 服务与场景调度设计</span></a></h1><blockquote><p>目的：细化推荐架构中的 AOI Service、Scene Orchestrator、ZoneServer 协同方案，确保跨场景可扩展、稳定、可监控。</p></blockquote><h2 id="_1-设计目标" tabindex="-1"><a class="header-anchor" href="#_1-设计目标"><span>1. 设计目标</span></a></h2><ol><li><strong>关注点分离</strong>：AOI（视野/空间计算）从 ZoneServer 脱离，减少逻辑线程负担。</li><li><strong>弹性伸缩</strong>：Scene Orchestrator 负责场景实例生命周期，可平滑扩容/释放。</li><li><strong>统一协议</strong>：AOI、Zone、Gate、Battle 使用统一消息格式（Protobuf），易于调试。</li><li><strong>容灾与监控</strong>：单个 AOI/Zone 故障只影响局部场景；提供健康检查、延迟监控。</li><li><strong>跨区视野</strong>：支持边缘玩家看到相邻区实体，必要时 AOI 可跨 Zone 合并视图。</li></ol><h2 id="_2-组件概览" tabindex="-1"><a class="header-anchor" href="#_2-组件概览"><span>2. 组件概览</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">┌─────────────────────────┐</span>
<span class="line">│ Scene Orchestrator      │</span>
<span class="line">│  • 场景实例管理          │</span>
<span class="line">│  • 资源池/复用           │</span>
<span class="line">│  • 调度/迁移             │</span>
<span class="line">└───┬────────────────────┘</span>
<span class="line">    │ scene_spawn(scene_id, config)</span>
<span class="line">    ▼</span>
<span class="line">┌─────────────────────────┐</span>
<span class="line">│ ZoneServer (多实例)     │</span>
<span class="line">│  • ECS/战斗/任务         │</span>
<span class="line">│  • 与 AOI 协同           │</span>
<span class="line">└───┬────────────────────┘</span>
<span class="line">    │ position_update / event</span>
<span class="line">    ▼</span>
<span class="line">┌─────────────────────────┐</span>
<span class="line">│ AOI Service (Cluster)   │</span>
<span class="line">│  • 空间索引（网格/四叉树）│</span>
<span class="line">│  • Enter/Leave 事件      │</span>
<span class="line">│  • AOI 广播过滤          │</span>
<span class="line">└───┬────────────────────┘</span>
<span class="line">    │ aoi_event / broadcast_targets</span>
<span class="line">    ▼</span>
<span class="line">┌─────────────────────────┐</span>
<span class="line">│ GateServer / Battle /   │</span>
<span class="line">│ Social services         │</span>
<span class="line">└─────────────────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_3-scene-orchestrator" tabindex="-1"><a class="header-anchor" href="#_3-scene-orchestrator"><span>3. Scene Orchestrator</span></a></h2><h3 id="_3-1-职责" tabindex="-1"><a class="header-anchor" href="#_3-1-职责"><span>3.1 职责</span></a></h3><ul><li>管理场景实例（static/dynamic）。支持副本池、Zone 绑定。</li><li>根据玩家请求或系统事件创建/销毁场景，调度到某个 ZoneServer。</li><li>维护 <code>scene_registry</code>：场景ID、类型、持有 Zone、AOI shard。</li><li>提供 API：<code>CreateScene</code>, <code>DestroyScene</code>, <code>TransferPlayer(SceneId, PlayerId)</code>。</li></ul><h3 id="_3-2-实现要点" tabindex="-1"><a class="header-anchor" href="#_3-2-实现要点"><span>3.2 实现要点</span></a></h3><ul><li><strong>资源池</strong>：预留一定数量的空闲场景，以降低瞬时创建成本。</li><li><strong>生命周期</strong>：见推荐架构的 Scene FSM（Create → Prepare → Active → EmptyCheck → Recycle）。</li><li><strong>容错</strong>：ZoneServer 异常时，可通知 Orchestrator 把场景迁移/销毁，并通知玩家重连或回滚。</li><li><strong>调度策略</strong>：按 CPU/内存负载、玩家数量选择 Zone；支持热迁移（通过同步状态 + 冷启动）。</li></ul><h2 id="_4-zoneserver" tabindex="-1"><a class="header-anchor" href="#_4-zoneserver"><span>4. ZoneServer</span></a></h2><h3 id="_4-1-职责" tabindex="-1"><a class="header-anchor" href="#_4-1-职责"><span>4.1 职责</span></a></h3><ul><li>承载实际游戏逻辑：ECS、AI、任务、技能、Buff、事件处理。</li><li>与 AOI Service 通信：上传位置、接收 Enter/Leave/Sync、广播结果。</li><li>与 DataProxy/Transport 协同保存状态、加载玩家。</li></ul><h3 id="_4-2-ecs-事件流" tabindex="-1"><a class="header-anchor" href="#_4-2-ecs-事件流"><span>4.2 ECS &amp; 事件流</span></a></h3><ol><li>玩家移动 → ZoneServer 更新 TransformComponent → 发送 <code>AOIUpdate</code> 给 AOI。</li><li>AOI 返回 <code>EnterSet/LeaveSet/Sync</code> → ZoneServer 触发逻辑（发消息、加载实体等）。</li><li>战斗/技能 → ZoneServer 自己处理逻辑（或调用 Battle Service），再根据 AOI 结果广播。</li></ol><h3 id="_4-3-线程模型" tabindex="-1"><a class="header-anchor" href="#_4-3-线程模型"><span>4.3 线程模型</span></a></h3><ul><li>ZoneServer 主线程处理 Tick（例如 20-30Hz），使用 Job System 处理复杂任务。</li><li>与 AOI 的通信通过 Transport（NNG TCP/IPC），采用异步 RPC 或消息队列。</li><li>需要缓冲来自 AOI 的事件（Enter/Leave）并按帧处理，避免频繁锁争用。</li></ul><h2 id="_5-aoi-service" tabindex="-1"><a class="header-anchor" href="#_5-aoi-service"><span>5. AOI Service</span></a></h2><h3 id="_5-1-数据结构" tabindex="-1"><a class="header-anchor" href="#_5-1-数据结构"><span>5.1 数据结构</span></a></h3><ul><li><strong>空间索引</strong>：建议使用层级化网格 + 四叉树： <ul><li>粗粒度：固定网格（例如 64x64m cell），快速定位 AOI shard。</li><li>细粒度：每个网格内用四叉树/邻接列表管理实体，支撑动态半径。</li></ul></li><li>支持 AOI 分片：将地图划分为多个 AOI shard，按玩家密度动态扩缩。</li></ul><h3 id="_5-2-功能" tabindex="-1"><a class="header-anchor" href="#_5-2-功能"><span>5.2 功能</span></a></h3><ul><li>接收 <code>PositionUpdate</code>（player_id, scene_id, pos, radius）。</li><li>计算 <code>EnterSet</code>, <code>LeaveSet</code>, <code>SyncList</code>，并返回给 Zone/Gate： <ul><li><code>EnterSet/LeaveSet</code>: 仅包含 entity_id、初始数据引用（位置、属性）。</li><li><code>SyncList</code>: 周期性发送 AOI 内实体的最新位置/状态。</li></ul></li><li>可选：提供 AOI 数据订阅给 GateServer，减少 ZoneServer 再广播的开销。</li><li>支持 AOI 规则：不同场景类型可定义 AOI 半径、过滤条件（阵营、隐身等）。</li></ul><h3 id="_5-3-通信接口-示例" tabindex="-1"><a class="header-anchor" href="#_5-3-通信接口-示例"><span>5.3 通信接口（示例）</span></a></h3><div class="language-protobuf line-numbers-mode" data-highlighter="prismjs" data-ext="protobuf"><pre><code class="language-protobuf"><span class="line"><span class="token keyword">message</span> <span class="token class-name">AOIUpdate</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token builtin">uint64</span> scene_id <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token builtin">uint64</span> entity_id <span class="token operator">=</span> <span class="token number">2</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token positional-class-name class-name">Vector3</span> position <span class="token operator">=</span> <span class="token number">3</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token builtin">float</span> aoi_radius <span class="token operator">=</span> <span class="token number">4</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token builtin">uint64</span> timestamp <span class="token operator">=</span> <span class="token number">5</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token positional-class-name class-name">EntityType</span> type <span class="token operator">=</span> <span class="token number">6</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">message</span> <span class="token class-name">AOIEvent</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token builtin">uint64</span> scene_id <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token builtin">uint64</span> entity_id <span class="token operator">=</span> <span class="token number">2</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">repeated</span> <span class="token builtin">uint64</span> enter_entities <span class="token operator">=</span> <span class="token number">3</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">repeated</span> <span class="token builtin">uint64</span> leave_entities <span class="token operator">=</span> <span class="token number">4</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">repeated</span> <span class="token positional-class-name class-name">AOISync</span> sync_entities <span class="token operator">=</span> <span class="token number">5</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-4-容灾" tabindex="-1"><a class="header-anchor" href="#_5-4-容灾"><span>5.4 容灾</span></a></h3><ul><li>AOI shard 之间支持状态复制（按场景/分区）。当某个 AOI 节点故障时，Orchestrator 将场景切换到备份或触发玩家回城。</li><li>AOI 与 Zone 的消息需具备幂等（sequence/timestamp），防止重复更新。</li><li>对于关键场景，可采用双写或快速快照（例如每 N 秒保存 AOI 索引状态）。</li></ul><h2 id="_6-battle-service-可选" tabindex="-1"><a class="header-anchor" href="#_6-battle-service-可选"><span>6. Battle Service（可选）</span></a></h2><ul><li>当需要专门的战斗计算（如大型团战）时，可将部分技能/结算 offload 到 Battle Service。</li><li>ZoneServer 发送战斗请求（技能、参与者、场景），Battle 计算后返回结果/广播指令。</li><li>AOI 仍由 AOI Service 负责，只是 ZoneServer 可能不再承担全部战斗逻辑。</li></ul><h2 id="_7-与-gate-guild-transport-的关系" tabindex="-1"><a class="header-anchor" href="#_7-与-gate-guild-transport-的关系"><span>7. 与 Gate/Guild/Transport 的关系</span></a></h2><ul><li>GateServer 只负责连接和消息路由，不直接参与 AOI。</li><li>AOI/Zone 之间通信使用前面定义的 Transport（NNG/IPC/TCP）： <ul><li>同机 Zone ↔ AOI：优先 IPC/共享内存。</li><li>跨机：NNG TCP。</li></ul></li><li>社交模块（Guild/Chat/Match）可订阅 AOI 事件（例如公会领地可见玩家），通过消息总线或 Transport 进行。</li></ul><h2 id="_8-监控与运维" tabindex="-1"><a class="header-anchor" href="#_8-监控与运维"><span>8. 监控与运维</span></a></h2><ul><li>关键指标：AOI 事件延迟、Enter/Leave 数量、AOI shard 负载、Zone tick 时间、场景数量、玩家迁移耗时。</li><li>提供管理命令：查看某场景的 AOI shard、强制迁移、Dump AOI 状态、追踪某玩家可见列表。</li><li>故障处理： <ol><li>AOI shard 不可用 → Orchestrator 标记场景 degrade，通知玩家回城或切换 shard。</li><li>ZoneServer 超载 → Orchestrator 调整场景分布、限流新玩家进入。</li><li>Scene crash → 触发重建/回收流程，日志记录。</li></ol></li></ul><h2 id="_9-实施-roadmap" tabindex="-1"><a class="header-anchor" href="#_9-实施-roadmap"><span>9. 实施 Roadmap</span></a></h2><ol><li><strong>Phase 1</strong>：基础版本（AOI Service + ZoneServer 接口 + Scene Orchestrator 管理），覆盖常规副本/野外。</li><li><strong>Phase 2</strong>：支持 AOI 分片、跨区视野、Battle Service offload。</li><li><strong>Phase 3</strong>：容灾/迁移（快速重建 AOI 数据）、监控工具。</li><li><strong>Phase 4</strong>：优化（共享内存通道、零拷贝、机器学习驱动 AOI 半径调整等）。</li></ol><hr><p>此设计为 AOI/场景模块提供统一蓝图，后续可以逐份文档（ZoneServer、AOI 协议、Scene Orchestrator 实施计划）展开，实现可扩展的视野/场景系统。***</p>`,37)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};